export class CommandPaletteEngine{constructor(e={}){this.isOpen=!1,this.selectedIndex=0,this.commands=e.commands||[{id:"home",title:"Go to Home",section:"Navigation",url:"index.html"},{id:"monuments",title:"Explore Monuments",section:"Heritage",url:"monuments.html"},{id:"culture",title:"Discover Arts & Culture",section:"Culture",url:"culture.html"},{id:"festivals",title:"Grand Festivals of India",section:"Culture",url:"festivals.html"},{id:"planner",title:"Trip & Itinerary Generator",section:"Travel",url:"itinery-generator.html"},{id:"map3d",title:"Interactive 3D Map",section:"Interactive",url:"india-3d-map.html"}],this.filteredCommands=[...this.commands]}toggle(){return this.isOpen=!this.isOpen,this.isOpen&&(this.selectedIndex=0,this.filteredCommands=[...this.commands]),this.isOpen}open(){this.isOpen=!0,this.selectedIndex=0,this.filteredCommands=[...this.commands]}close(){this.isOpen=!1}search(e){const t=(e||"").toLowerCase().trim();return this.filteredCommands=t?this.commands.filter(e=>e.title.toLowerCase().includes(t)||e.section.toLowerCase().includes(t)):[...this.commands],this.selectedIndex=0,this.filteredCommands}navigate(e){return 0===this.filteredCommands.length?0:("down"===e?this.selectedIndex=(this.selectedIndex+1)%this.filteredCommands.length:"up"===e&&(this.selectedIndex=(this.selectedIndex-1+this.filteredCommands.length)%this.filteredCommands.length),this.selectedIndex)}getSelectedCommand(){return 0===this.filteredCommands.length?null:this.filteredCommands[this.selectedIndex]||null}}